@sig trait TemperatureQualificationOwner_Api {
  def id: Art.BridgeId
  def temperature_report_Id : Art.PortId
  def qualified_temperature_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualified_temperature: Protected_Start_Power_Supervisor.QualifiedTemperature.Type = $

  def put_qualified_temperature(value : Protected_Start_Power_Supervisor.QualifiedTemperature.Type) : Unit = {
    Contract(
      Modifies(qualified_temperature),
      Ensures(
        qualified_temperature == value
      )
    )
    Spec {
      qualified_temperature = value
    }

    Art.putValue(qualified_temperature_Id, Protected_Start_Power_Supervisor.QualifiedTemperature_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class TemperatureQualificationOwner_Initialization_Api (
  val id: Art.BridgeId,
  val temperature_report_Id : Art.PortId,
  val qualified_temperature_Id : Art.PortId) extends TemperatureQualificationOwner_Api

@datatype class TemperatureQualificationOwner_Operational_Api (
  val id: Art.BridgeId,
  val temperature_report_Id : Art.PortId,
  val qualified_temperature_Id : Art.PortId) extends TemperatureQualificationOwner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var temperature_report: Protected_Start_Power_Supervisor.TemperatureReport = $

  def get_temperature_report() : Option[Protected_Start_Power_Supervisor.TemperatureReport] = {
    Contract(
      Ensures(
        Res == Some(temperature_report)
      )
    )
    val value : Option[Protected_Start_Power_Supervisor.TemperatureReport] = Art.getValue(temperature_report_Id) match {
      case Some(Protected_Start_Power_Supervisor.TemperatureReport_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port temperature_report.  Expecting 'Protected_Start_Power_Supervisor.TemperatureReport_Payload' but received ${v}")
        None[Protected_Start_Power_Supervisor.TemperatureReport]()
      case _ => None[Protected_Start_Power_Supervisor.TemperatureReport]()
    }
    return value
  }
}
